(()=>{function e(){const n=$fx.getParam("bgCol").hex.rgba;var a;a=n.replace("#",""),parseInt(a,16),document.body.style.background=n,document.body.innerHTML="\n  ";const o=document.createElement("button");o.textContent="emit random params",o.addEventListener("click",(()=>{$fx.emit("params:update",{number_id:$fx.getRandomParam("number_id"),bigint_id:$fx.getRandomParam("bigint_id"),string_id_long:$fx.getRandomParam("string_id_long"),select_id:$fx.getRandomParam("select_id"),color_id:$fx.getRandomParam("color_id"),boolean_id:$fx.getRandomParam("boolean_id"),string_id:$fx.getRandomParam("string_id")}),e()}))}new URLSearchParams(window.location.search),$fx.params([{id:"number_id",name:"Number of Lines Iterations (Recommended number is 50000, but for calculation time issues, around 1:30 minutes, default value is at 10000)",type:"number",default:1e4,options:{min:1,max:1e5,step:1}},{id:"sphere_num",name:"Iterations over sphere generation",type:"number",default:500,options:{min:1,max:5e3,step:1}},{id:"displacementAndTurnSpeed",name:"Line Displacement step speed (Recommended number is default value)",type:"number",default:.25,options:{min:.01,max:1,step:1e-4}},{id:"totalLineLengh",name:"Total Line length (same)",type:"number",default:.15,options:{min:.01,max:1,step:1e-4}},{id:"LineBaseAlpha",name:"Alpha of line appearance",type:"number",default:45.5,options:{min:0,max:255,step:.001}},{id:"bgCol",name:"Background Color",type:"color",default:"#b0a7901a"},{id:"LineColor_01",name:"First Line Color",type:"color",default:"#E1A50E19"},{id:"LineColor_02",name:"Second Line Color",type:"color",default:"#E39EC119"},{id:"LineColor_03",name:"Third Line Color",type:"color",default:"#3581B819"},{id:"LineColor_04",name:"Fourth Line Color",type:"color",default:"#E39EC119"},{id:"LineColor_05",name:"Fifth Line Color",type:"color",default:"#C47AC019"}]),e(),$fx.on("params:update",(e=>5!==e.number_id),((n,a)=>e()))})();